    for s in marks:
        if s in seen: continue
        comp=[]; q=deque([s]); seen.add(s)
        while q:
            r,c=q.popleft(); comp.append((r,c))
            for dr in(-1,0,1):
                for dc in(-1,0,1):
                    n=(r+dr,c+dc)
                    if n in marks and n not in seen:
                        seen.add(n); q.append(n)
        comps.append(comp)
    return comps
