    for s in M:
        if s in seen: continue
        q=[s]; seen.add(s); comp=[]
        while q:
            r,c=q.pop(); comp.append((r,c))
            for dr in(-1,0,1):
                for dc in(-1,0,1):
                    n=(r+dr,c+dc)
                    if n in M and n not in seen: seen.add(n); q.append(n)
        out.append(comp)
    return out
def solve(g,marker,bg,dv):
    H,W=len(g),len(g[0])
    dvrows=[i for i,r in enumerate(g) if all(x==dv for x in r)]
    dvcols=[j for j in range(W) if all(g[i][j]==dv for i in range(H))]
    rb=sorted(dvrows)+[-1]; cb=sorted(dvcols)+[-1]
    bands_r=[]; prev=-1
    for x in rb+[H]:
        if x-prev>1: bands_r.append((prev+1,x))
        prev=x
    bands_c=[]; prev=-1
    for x in cb+[W]:
        if x-prev>1: bands_c.append((prev+1,x))
        prev=x
    def bandsum(r0,r1,c0,c1): return sum(g[r][c]==marker for r in range(r0,r1+1) for c in range(c0,c1+1))
    best=max(bandsum(*b) for b in [(a,bd) for a in bands_r for bd in bands_c])
    res=[[bg]*W for _ in range(H)]
    for (r0,r1) in bands_r:
        for (c0,c1) in bands_c:
            if bandsum(r0,r1,c0,c1)==best:
                for r in range(r0,r1+1):
                    for c in range(c0,c1+1): res[r][c]=marker
    # dividers as-is
    for r in dvrows:
        for c in range(W): res[r][c]=dv
    for c in dvcols:
        for r in range(H): res[r][c]=dv
    return res
